/**
 * OpenCut sample - "Second Tour" (34 s, 1920x1080 @ 30 fps)
 *
 * The scenes `atlas.ts` could not cover: imported media, a per-scene camera, a
 * component that nests another component, the synthesized voice channel and a
 * film-wide vignette. There is no global camera here on purpose - a scene
 * camera only runs when the film does not declare one.
 *
 * Assets live in `films/assets` and are regenerated by the two commands below,
 * so the film stays reproducible without shipping anything heavy.
 *
 *   ffmpeg -f lavfi -i "color=c=0x0d1a36:s=960x540,\
 *     drawgrid=w=80:h=80:t=2:c=0x2a4a80@0.6,format=rgba" -frames:v 1 grid.png
 *   ffmpeg -f lavfi -i "testsrc=size=320x180:rate=30:duration=2" \
 *     -c:v libx264 -pix_fmt yuv420p -crf 28 pulse.mp4
 *
 * Run: node --experimental-strip-types films/tour.ts tour.mp4
 */
import { fileURLToPath, pathToFileURL } from 'node:url';
import {
    Film,
    callout,
    card,
    colorToken,
    counter,
    footnote,
    glow,
    grain,
    image,
    instance,
    path,
    shape,
    text,
    video,
} from '@wae/open-cut';

const asset = (name: string) => fileURLToPath(new URL(`./assets/${name}`, import.meta.url));

// A vignette is a film-wide look, declared once instead of per scene.
const film = new Film({ width: 1920, height: 1080, fps: 30, supersample: 1.5, post: { vignette: 0.35 } });

film.design({
    colors: [
        { role: 'ink', value: '#e6eefa', locked: true },
        { role: 'muted', value: '#8fa3c8' },
        { role: 'accent', value: '#7aa2ff' },
        { role: 'warm', value: '#e8b86d' },
    ],
});

// Nested reuse: `panel` embeds two instances of `dot`, so one definition still
// drives every level of the placement.
film.component('dot', [
    shape({ at: 0, dur: 6, shape: 'circle', x: 0.5, y: 0.5, w: 0.16, h: 0.16, color: colorToken('warm'), fadeIn: 0.3 }),
    shape({ at: 0, dur: 6, shape: 'ring', x: 0.5, y: 0.5, w: 0.45, h: 0.45, color: colorToken('warm'), stroke: 14, fadeIn: 0.3 }),
]);
film.component('panel', [
    shape({ at: 0, dur: 6, shape: 'rect', x: 0.5, y: 0.5, w: 1.0, h: 1.0, color: '#16233f', radius: 20, fadeIn: 0.3 }),
    instance({ at: 0, dur: 6, component: 'dot', x: 0.5, y: 0.36, w: 0.5, h: 0.5, opacity: 1 }),
    instance({ at: 0.4, dur: 5.6, component: 'dot', x: 0.5, y: 0.68, w: 0.32, h: 0.32, opacity: 0.65 }),
]);

film.scene({
    id: 'still',
    duration: 6,
    background: { kind: 'v-gradient', colors: ['#070d1c', '#101c36', '#04060f'] },
    items: [
        // A panel behind the still, not on top of it: shapes paint filled, so
        // order is the only way to frame an image.
        shape({ at: 0.2, dur: 5.6, shape: 'rect', x: 0.5, y: 0.58, w: 0.66, h: 0.6, color: '#16233f', radius: 14, fadeIn: 0.6 }),
        image({ at: 0.3, dur: 5.5, src: asset('grid.png'), x: 0.5, y: 0.58, w: 0.62, h: 0.56, fit: 'cover', opacity: 0.9, radius: 10, fadeIn: 0.6 }),
        text({
            at: 0.6,
            dur: 5.2,
            content: 'Imported still',
            sub: 'a decoded PNG placed as a scene node',
            size: 46,
            bold: true,
            color: colorToken('ink'),
            subColor: colorToken('muted'),
            x: 0.5,
            y: 0.13,
            rise: 16,
            stagger: 2,
        }),
        footnote({ at: 1.0, dur: 4.6, text: 'assets/grid.png - 960x540, generated by ffmpeg, not shipped artwork', x: 0.5, y: 0.93, size: 21, align: 'center' }),
        grain({ at: 0, dur: 6, strength: 0.04, density: 12000 }),
    ],
});

film.scene({
    id: 'clip',
    duration: 7,
    background: { kind: 'v-gradient', colors: ['#050a16', '#0d1830', '#03050c'] },
    items: [
        text({
            at: 0.3,
            dur: 6.4,
            content: 'Imported clip',
            sub: 'source frames decoded through the host codec',
            size: 44,
            bold: true,
            color: colorToken('ink'),
            subColor: colorToken('muted'),
            x: 0.5,
            y: 0.14,
            rise: 14,
            stagger: 2,
        }),
        video({ at: 0.4, dur: 6.0, src: asset('pulse.mp4'), x: 0.38, y: 0.58, w: 0.48, h: 0.5, fit: 'contain', radius: 10, fadeIn: 0.5 }),
        card({
            at: 1.2,
            dur: 5.2,
            x: 0.79,
            y: 0.54,
            w: 0.22,
            h: 0.24,
            title: 'srcIn',
            body: 'the clip starts at the frame you choose, not at zero',
            accent: colorToken('accent'),
        }),
        footnote({ at: 1.0, dur: 5.4, text: 'assets/pulse.mp4 - 2 s of generated test frames', x: 0.5, y: 0.93, size: 21, align: 'center' }),
        grain({ at: 0, dur: 7, strength: 0.04, density: 13000 }),
    ],
});

film.scene({
    id: 'push',
    duration: 7,
    background: { kind: 'v-gradient', colors: ['#0a1024', '#16203d', '#05070f'] },
    // A scene camera only runs when the film declares no global curve.
    camera: { zoomFrom: 1.0, zoomTo: 1.34, focusFrom: [0.5, 0.55], focusTo: [0.56, 0.5], ease: 'in-out-cubic' },
    items: [
        path({
            at: 0,
            dur: 7,
            points: [[0.0, 0.78], [0.18, 0.66], [0.38, 0.72], [0.56, 0.6], [0.74, 0.68], [0.9, 0.62], [1.0, 0.7], [1.0, 1.0], [0.0, 1.0]],
            smooth: true,
            closed: true,
            fill: '#0c1528',
        }),
        path({
            at: 0,
            dur: 7,
            points: [[0.0, 0.78], [0.18, 0.66], [0.38, 0.72], [0.56, 0.6], [0.74, 0.68], [0.9, 0.62], [1.0, 0.7]],
            smooth: true,
            stroke: 3,
            color: colorToken('accent'),
            progress: 1,
            blend: 'add',
        }),
        glow({ at: 0, dur: 7, x: 0.62, y: 0.48, radius: 0.14, color: colorToken('warm'), intensity: 0.4 }),
        text({ at: 0.4, dur: 6.2, content: 'Scene camera', sub: 'one push per block, no global curve', size: 42, bold: true, color: colorToken('ink'), subColor: colorToken('muted'), x: 0.5, y: 0.2, rise: 14, stagger: 2 }),
        grain({ at: 0, dur: 7, strength: 0.05, density: 14000 }),
    ],
});

film.scene({
    id: 'nested',
    duration: 6,
    background: { kind: 'v-gradient', colors: ['#060b18', '#0f1a33', '#03050b'] },
    items: [
        text({ at: 0.3, dur: 5.4, content: 'Nested components', sub: 'a panel that is built from two placed dots', size: 42, bold: true, color: colorToken('ink'), subColor: colorToken('muted'), x: 0.5, y: 0.16, rise: 14, stagger: 2 }),
        instance({ at: 0.6, dur: 5.0, component: 'panel', x: 0.34, y: 0.52, w: 0.24, h: 0.34, opacity: 1 }),
        instance({ at: 0.9, dur: 4.7, component: 'panel', x: 0.66, y: 0.52, w: 0.24, h: 0.34, opacity: 0.75 }),
        footnote({ at: 1.2, dur: 4.2, text: 'one `panel` definition, two placements, each drawing its own `dot` instances', x: 0.5, y: 0.93, size: 21, align: 'center' }),
        grain({ at: 0, dur: 6, strength: 0.04, density: 12000 }),
    ],
});

film.scene({
    id: 'voice',
    duration: 5,
    background: { kind: 'v-gradient', colors: ['#081020', '#13203c', '#04060d'] },
    items: [
        text({ at: 0.2, dur: 4.6, content: 'Synthesized voice', sub: 'syllables, pitch and tempo - no recorded audio', size: 42, bold: true, color: colorToken('ink'), subColor: colorToken('muted'), x: 0.5, y: 0.16, rise: 14, stagger: 2 }),
        counter({ at: 0.6, dur: 4.0, from: 0, to: 8, suffix: ' syllables', size: 52, color: colorToken('warm'), x: 0.5, y: 0.5, decimals: 0 }),
        callout({ at: 1.6, dur: 3.0, ax: 0.5, ay: 0.62, x: 0.66, y: 0.76, text: 'a e i o u', note: 'the five contracted vowels', size: 22, color: colorToken('accent'), panel: '#101a34', elbow: true }),
        footnote({ at: 1.0, dur: 3.8, text: 'the voice channel is mixed into the same bed as the effects', x: 0.5, y: 0.93, size: 21, align: 'center' }),
        grain({ at: 0, dur: 5, strength: 0.04, density: 12000 }),
    ],
});

film.scene({
    id: 'close',
    duration: 3,
    background: { kind: 'v-gradient', colors: ['#05080f', '#0b1424', '#02040a'] },
    items: [
        // The vignette is only obvious at the edges, so this scene keeps the
        // frame quiet and lets the corners show the look.
        text({ at: 0.2, dur: 2.7, content: 'Second tour complete', size: 40, color: colorToken('muted'), x: 0.5, y: 0.46, rise: 12, stagger: 2 }),
        footnote({ at: 0.4, dur: 2.5, text: 'vignette, imported media, scene camera, nested components and voice', x: 0.5, y: 0.93, size: 21, align: 'center' }),
    ],
});

film.audio({
    bgm: { volume: 0.04 },
    sfx: [
        { at: 0.1, kind: 'sub', volume: 0.3 },
        { at: 6.0, kind: 'whoosh', volume: 0.24 },
        { at: 20.0, kind: 'tick', volume: 0.24 },
        { at: 26.0, kind: 'sparkle', volume: 0.18 },
    ],
    voice: [
        {
            at: 26.2,
            volume: 0.5,
            song: {
                tempoBpm: 96,
                syllables: [
                    { onset: 's', vowel: 'a', pitch: 392, beats: 0.5 },
                    { vowel: 'e', pitch: 440, beats: 0.5 },
                    { onset: 'n', vowel: 'i', pitch: 494, beats: 0.5 },
                    { vowel: 'o', pitch: 440, beats: 0.5 },
                    { onset: 'w', vowel: 'u', pitch: 392, beats: 1 },
                ],
            },
        },
    ],
    notes: [
        { at: 0.5, instrument: 'pad', note: 50, duration: 5.0, velocity: 0.4 },
        { at: 13.2, instrument: 'strings', note: 45, duration: 6.0, velocity: 0.36 },
        { at: 20.4, instrument: 'marimba', note: 72, duration: 1.2, velocity: 0.4 },
        { at: 26.4, instrument: 'bell', note: 76, duration: 1.6, velocity: 0.3 },
    ],
});

export default film;

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
    const stats = film.render(process.argv[2] ?? 'tour.mp4');
    console.log(`rendered ${stats.frames} frames (${stats.seconds.toFixed(1)}s) -> ${stats.out}`);
    console.log(`backend: ${stats.backend} · audio: ${stats.audio}`);
}
